(function(E){ const x = E["hr-m1"] = E["hr-m1"] || {units:{}}; x.units["hr-1-4"] = {"explain":{"id":"c-hr-1-4-e","course":"hr","unit":"hr-1-4","type":"explain","level":"B1","title":{"en":"Small talk and rapport","tr":"Sohbet ve yakınlık kurmak","fa":"گپ کوتاه و ایجاد رابطه‌ی گرم"},"objective":{"en":"After this lesson, you can start, keep going and end a short small talk with a visitor.","tr":"Bu dersin sonunda bir ziyaretçiyle kısa bir sohbeti başlatabilecek, sürdürebilecek ve kibarca bitirebileceksin.","fa":"بعد از این درس می‌توانی با یک مهمان گپ کوتاهی را شروع کنی، ادامه بدهی و تمام کنی."},"hook":{"en":"Keep small talk short and take turns. A few minutes of easy talk help a visitor relax before the real conversation. In the lobby Leyla asks 'Have you ever...?', then tells her own story with 'I went...'. Two tenses, one chat.","tr":"Sohbeti kısa tut ve sırayla konuş. Birkaç dakikalık rahat bir sohbet, asıl görüşmeden önce ziyaretçinin rahatlamasına yardım eder. Lobide Leyla 'Have you ever...?' diye soruyor, sonra kendi hikâyesini 'I went...' ile anlatıyor. Bir sohbette iki zaman.","fa":"گپ را کوتاه نگه دار و نوبتی حرف بزن. چند دقیقه گپ راحت کمک می‌کند مهمان قبل از گفتگوی اصلی آرام شود. لیلا در لابی می‌پرسد «Have you ever...?» و بعد ماجرای خودش را با «⁨I went...⁩» تعریف می‌کند. یک گپ، دو زمان."},"before":{"en":"Write a short, friendly welcome to a candidate before an interview, with one small-talk question.","tr":"Bir görüşmeden önce adaya kısa ve samimi bir karşılama mesajı yaz; içinde bir sohbet sorusu olsun.","fa":"قبل از مصاحبه یک پیام خوشامد کوتاه و دوستانه برای داوطلب بنویس، با یک سؤال گپ‌وگفت."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Ask, answer briefly, ask back","tr":"Sor, kısa cevap ver, sen de sor","fa":"بپرس، کوتاه جواب بده، تو هم بپرس"},"body":{"en":"Small talk goes in turns. Choose a safe topic, like the journey. Give a short answer, then ask back. Then close it and move on to business.","tr":"Sohbet sırayla ilerler. Yolculuk gibi güvenli bir konu seç. Kısa cevap ver, sonra sen de sor. Ardından sohbeti kapat ve işe geç.","fa":"گپ کوتاه نوبتی پیش می‌رود. موضوعی بی‌خطر مثل مسیر رسیدن را انتخاب کن. کوتاه جواب بده و بعد تو هم بپرس. بعد گپ را جمع کن و سراغ کار برو."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Talking about experience","tr":"Deneyimden bahsetmek","fa":"حرف زدن از تجربه"},"steps":[{"en":"Experience, time not important: have/has + past participle.","tr":"Deneyim, zaman önemli değil: have/has + past participle.","fa":"برای تجربه، وقتی زمانش مهم نیست، have/has و اسم مفعول می‌آید.","ex":"I've been to Dubai twice."},{"en":"A finished time (last year, in 2019): past simple.","tr":"Bitmiş bir zaman (last year, in 2019): past simple.","fa":"برای زمان تمام‌شده (last year، in 2019) گذشته‌ی ساده می‌آید.","ex":"I went there last spring."},{"en":"Short answer, then ask back.","tr":"Kısa cevap ver, sonra soruyu geri sor.","fa":"جواب کوتاه بده و همان سؤال را برگردان.","ex":"Yes, twice. Have you?"}],"table":{"headers":{"en":["Idea","Pattern"],"tr":["Fikir","Kalıp"],"fa":["منظور","الگو"]},"rows":[["Ask about experience","Have you ever been to...?"],["Answer without a time","I've been there twice."],["Answer with a time","I went there last year."],["Return the question","And you? / How about you?"]]},"tip":{"en":"Turkish gittim covers both experience and a finished time, and Persian often says parsal rafte-am with a finished time. English separates them: a finished time + present perfect is always wrong.","tr":"Türkçede 'Dubai'ye gittim' hem deneyim hem belirli bir zaman için kullanılabilir. İngilizcede ayrım katıdır: zaman belliyse (last year) present perfect kullanılmaz: I went there last year.","fa":"در فارسی «پارسال دبی رفته‌ام» هم شنیده می‌شود و زمان تمام‌شده با شکلی شبیه حال کامل می‌آید. در انگلیسی این ممکن نیست: last year با حال کامل همیشه غلط است: «⁨I went there last year.⁩»"},"wrong":"I have visited Dubai last year.","right":"I visited Dubai last year."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"Did you find us okay?","meaning":{"en":"Friendly opener for a visitor.","tr":"Ziyaretçi için samimi açılış.","fa":"شروعی دوستانه برای مهمانی که تازه رسیده است."}},{"phrase":"Have you ever been to...?","meaning":{"en":"Asks about experience.","tr":"Deneyim sorar.","fa":"درباره‌ی تجربه‌ی کسی می‌پرسد."}},{"phrase":"Shall we make a start?","meaning":{"en":"Moves from small talk to business.","tr":"Sohbetten işe geçer.","fa":"از گپ به سراغ اصل کار می‌رود."}},{"phrase":"small talk","meaning":{"en":"Light conversation about unimportant topics.","tr":"havadan sudan sohbet.","fa":"صحبت سبک و دوستانه درباره‌ی موضوع‌های کم‌اهمیت"}},{"phrase":"How was your journey?","meaning":{"en":"A safe question to open a conversation.","tr":"Yolculuk nasıldı?","fa":"مسیر چطور بود؟ راحت رسیدید؟"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Small talk: watch and adjust","tr":"Sohbet: karşındakini izle, uyum sağla","fa":"گپ کوتاه: واکنش طرف را ببین و خودت را تنظیم کن"},"body":{"en":"In the UK and US, a few minutes of light talk before business is normal and often expected. In some other cultures, getting to the point fast shows respect for time. Neither is wrong: watch how the other person reacts and adjust.","tr":"Birleşik Krallık ve ABD'de işe girmeden önce birkaç dakika hafif sohbet normaldir, çoğu zaman beklenir. Bazı kültürlerde hemen konuya girmek zamana saygıdır. İkisi de yanlış değil: karşındakinin tepkisine bakıp uyum sağla.","fa":"در بریتانیا و آمریکا چند دقیقه گپ سبک پیش از شروع کار عادی است و اغلب از تو انتظار می‌رود. در بعضی فرهنگ‌های دیگر، زود رفتن سر اصل مطلب نشانه‌ی احترام به وقت دیگران است. هیچ‌کدام غلط نیست؛ واکنش طرف مقابل را ببین و خودت را با آن هماهنگ کن."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از سکوت تا گپ نوبتی"},"text":"Facts: Your own journey was slow.","item":"How old are you? Are you married?","why":{"en":"Weak: personal questions, then silence. Strong: a safe question, a short answer, a question back.","tr":"Zayıf: kişisel sorular, sonra sessizlik. Güçlü: güvenli bir soru, kısa bir cevap, karşı bir soru.","fa":"نسخه‌ی اول سؤال شخصی می‌پرسد و بعد سکوت است. نسخه‌ی دوم یک سؤال بی‌خطر می‌پرسد، کوتاه جواب می‌دهد و بعد خودش هم می‌پرسد."},"answer":"How was your journey? Mine was slow too. Have you been here before?","cut":["How old are you?","Are you married?"],"cutHint":{"en":"Tap the questions that are not safe small talk.","tr":"Güvenli sohbet konusu olmayan sorulara dokun.","fa":"روی سؤال‌هایی بزن که موضوع امنی برای گپ‌وگفت نیستند."}},"quick":{"prompt":"The candidate says: \"Fine, thanks. The traffic was terrible!\" What is the best next move?","options":["Answer briefly and ask back: \"Mine too. Was it hard to find us?\"","Tell a long story about your own traffic","Start the interview questions straight away"],"correct":0,"why":{"en":"Answer briefly and ask back: small talk goes in turns. After a turn or two, close it and move on to business.","tr":"Kısa cevap ver ve karşı soru sor: Sohbet sırayla ilerler. Bir iki turdan sonra kapat ve işe geç.","fa":"کوتاه جواب بده و سؤال متقابل بپرس: گپ‌وگفت نوبتی پیش می‌رود. بعد از یکی دو نوبت تمامش کن و برو سر کار اصلی."},"point":1},"remember":{"en":"Is there a finished time word (last, ago, in 2019, yesterday)? Then no have: use the past simple. Result of this lesson: you can start, keep going and end a short chat. You also have a friendly welcome message.","tr":"Bitmiş bir zaman ifadesi var mı (last, ago, in 2019, yesterday)? O zaman have yok: past simple kullan. Bu dersin sonucu: kısa bir sohbeti başlatıp sürdürebilir ve bitirebilirsin; elinde de samimi bir karşılama mesajı olur.","fa":"کلمه‌ای برای زمان تمام‌شده هست (last، ago، in 2019، yesterday)؟ پس have نمی‌آید: گذشته‌ی ساده بنویس. حالا می‌توانی گپی کوتاه را شروع کنی، ادامه بدهی و تمام کنی. یک پیام خوشامد صمیمی هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Question tags in small talk","tr":"Sohbette onay soruları (question tags)","fa":"سؤال‌های تأییدی (question tags) در گپ"},"steps":[{"en":"Repeat the helper verb and the pronoun.","tr":"Yardımcı fiili ve zamiri tekrar et.","fa":"فعل کمکی و ضمیر را تکرار کن.","ex":"You're Deniz, aren't you?"},{"en":"No helper in the statement? Use do, does or did.","tr":"Cümlede yardımcı fiil yok mu? do, does ya da did kullan.","fa":"در جمله فعل کمکی نیست؟ از do، does یا did استفاده کن.","ex":"You came by bus, didn't you?"},{"en":"Positive statement, negative tag; negative statement, positive tag.","tr":"Olumlu cümleye olumsuz onay sorusu; olumsuz cümleye olumlu onay sorusu.","fa":"بعد از جمله‌ی مثبت tag منفی می‌آید و بعد از جمله‌ی منفی tag مثبت.","ex":"You haven't been here before, have you?"}],"table":{"headers":{"en":["Statement","Tag"],"tr":["Cümle","Onay sorusu"],"fa":["جمله","tag"]},"rows":[["You're Deniz,","aren't you?"],["You came by bus,","didn't you?"],["You haven't been to Dubai before,","have you?"],["It's hot today,","isn't it?"]]},"body":{"en":"B2 track: use at least two question tags in the lobby small talk, one after a positive and one after a negative statement.","tr":"B2 yolu: lobideki sohbette en az iki onay sorusu (question tag) kullan; biri olumlu, biri olumsuz bir cümleden sonra.","fa":"مسیر B2: در گپ لابی دست‌کم دو question tag به کار ببر: یکی بعد از جمله‌ی مثبت و یکی بعد از جمله‌ی منفی."}}},"grammar":{"id":"c-hr-1-4-g","level":"B1","course":"hr","unit":"hr-1-4","title":"Talking about experience","titleTr":"Deneyimden bahsetmek","exp":{"en":"Small talk often asks about experience, not about one exact time: \"Have you ever been to Dubai?\" Use have/has + past participle when the time is not important: \"I've been to Dubai twice.\" As soon as you give a finished time (last year, in 2019), switch to the past simple: \"I went there last year.\" Do not say \"I have been there last year\". A good small-talk move is a short answer plus a question back: \"Yes, twice. Have you?\" Keep topics safe: travel, the journey, weather, food, the city. Avoid money, politics, religion and age.","tr":"Sohbet genelde belirli bir zamanı değil, deneyimi sorar: \"Have you ever been to Dubai?\" Zaman önemli değilse have/has + past participle kullan: \"I've been to Dubai twice.\" Bitmiş bir zaman söylediğin an (last year, in 2019) past simple'a geç: \"I went there last year.\" \"I have been there last year\" deme. İyi bir sohbet hamlesi kısa cevap ve karşı soru: \"Yes, twice. Have you?\" Güvenli konular: seyahat, yolculuk, hava, yemek, şehir. Para, siyaset, din ve yaştan kaçın.","fa":"گپ‌های کوتاه معمولاً درباره‌ی تجربه است، نه یک زمان مشخص: «⁨Have you ever been to Dubai?⁩» وقتی زمانِ اتفاق مهم نیست، از have/has + اسم مفعول (حال کامل) استفاده کن: «⁨I've been to Dubai twice.⁩» اما به محض اینکه زمانی تمام‌شده را نام ببری (last year، in 2019)، باید به گذشته‌ی ساده بروی: «⁨I went there last year.⁩» پس «I have been there last year» غلط است. فارسی‌زبان‌ها این را زیاد اشتباه می‌کنند، چون در فارسی «پارسال دبی رفته‌ام» هم شنیده می‌شود. یک حرکت خوب در گپ: جواب کوتاه بده و همان سؤال را برگردان: «⁨Yes, twice. Have you?⁩» موضوع‌های امن: سفر، مسیر رسیدن، هوا، غذا و شهر. از پول، سیاست، مذهب و سن پرهیز کن."},"formsTable":{"headers":{"en":["Idea","Pattern"],"tr":["Fikir","Kalıp"],"fa":["منظور","الگو"]},"rows":[["Ask about experience","Have you ever been to...?"],["Answer without a time","I've been there twice."],["Answer with a time","I went there last year."],["Return the question","And you? / How about you?"]]},"wrong":"I have been to Dubai last year.","right":"I went to Dubai last year.","blank":{"sentence":"I ___ to Dubai twice.","word":"have been","distractors":["was","am being"]},"wrong2":"Have you ever have a long interview in English?","right2":"Have you ever had a long interview in English?","blank2":{"sentence":"Have you ever ___ a long interview in English?","word":"had","distractors":["have","having"]},"expParts":{"hook":{"en":"In the lobby Leyla asks 'Have you ever...?', then tells her own story with 'I went...'. Two tenses, one chat.","tr":"Lobide Leyla 'Have you ever...?' diye soruyor, sonra kendi hikâyesini 'I went...' ile anlatıyor. Bir sohbette iki zaman.","fa":"لیلا در لابی می‌پرسد «Have you ever...?» و بعد ماجرای خودش را با «⁨I went...⁩» تعریف می‌کند. یک گپ، دو زمان."},"tryWhy":{"en":"had: after 'Have you ever' comes the past participle. have becomes had.","tr":"had: 'Have you ever'dan sonra past participle gelir. have, had olur.","fa":"جواب had است: بعد از Have you ever اسم مفعول می‌آید و have می‌شود had."},"rule":[{"en":"Experience, time not important: have/has + past participle.","tr":"Deneyim, zaman önemli değil: have/has + past participle.","fa":"برای تجربه، وقتی زمانش مهم نیست، have/has و اسم مفعول می‌آید.","ex":"I've been to Dubai twice."},{"en":"A finished time (last year, in 2019): past simple.","tr":"Bitmiş bir zaman (last year, in 2019): past simple.","fa":"برای زمان تمام‌شده (last year، in 2019) گذشته‌ی ساده می‌آید.","ex":"I went there last spring."},{"en":"Short answer, then ask back.","tr":"Kısa cevap ver, sonra soruyu geri sor.","fa":"جواب کوتاه بده و همان سؤال را برگردان.","ex":"Yes, twice. Have you?"}],"test":{"en":"Is there a finished time word (last, ago, in 2019, yesterday)? Then no have: use the past simple.","tr":"Bitmiş bir zaman ifadesi var mı (last, ago, in 2019, yesterday)? O zaman have yok: past simple kullan.","fa":"کلمه‌ای برای زمان تمام‌شده هست (last، ago، in 2019، yesterday)؟ پس have نمی‌آید: گذشته‌ی ساده بنویس."},"contrast":{"en":"Turkish gittim covers both experience and a finished time, and Persian often says parsal rafte-am with a finished time. English separates them: a finished time + present perfect is always wrong.","tr":"Türkçede 'Dubai'ye gittim' hem deneyim hem belirli bir zaman için kullanılabilir. İngilizcede ayrım katıdır: zaman belliyse (last year) present perfect kullanılmaz: I went there last year.","fa":"در فارسی «پارسال دبی رفته‌ام» هم شنیده می‌شود و زمان تمام‌شده با شکلی شبیه حال کامل می‌آید. در انگلیسی این ممکن نیست: last year با حال کامل همیشه غلط است: «⁨I went there last year.⁩»"}},"errorWatch":[{"find":["have been to dubai last","have been there last","has been there last","have been to istanbul last","have visited dubai last","have been there yesterday","have been there in 2019","have seen it last","have met him last","have met her last"],"fix":{"en":"A finished time needs the past simple: 'I went there last year.'","tr":"Bitmiş bir zaman past simple ister: 'I went there last year.'","fa":"زمان تمام‌شده گذشته‌ی ساده می‌خواهد: «⁨I went there last year.⁩»"}},{"find":["have you ever have","have you ever went","have you ever saw","have you ever go","has he ever have","have you ever visit"],"fix":{"en":"After 'Have you ever' use the past participle: had, been, seen, visited.","tr":"'Have you ever'dan sonra past participle kullan: had, been, seen, visited.","fa":"بعد از «Have you ever» اسم مفعول بیاور: had، been، seen، ⁨visited⁩."}}]},"b2":{"id":"c-hr-1-4-b2","level":"B2","track":"B2","course":"hr","unit":"hr-1-4","title":"Question tags in small talk","titleTr":"Sohbette onay soruları (question tags)","exp":{"en":"A question tag is a short question at the end of a statement: \"You're Deniz, aren't you?\", \"The traffic was terrible, wasn't it?\" In small talk it invites the other person to agree and keep talking. Build it from the statement: repeat the auxiliary (am/is/are, do/does/did, have, can, will) and the pronoun, and flip positive to negative: \"You came by bus, didn't you?\", \"You haven't been to Dubai before, have you?\" Turkish \"değil mi?\" and Farsi «نه؟» stay the same every time, so learners often say \"isn't it?\" after everything. In English the tag must match: \"You came by bus, isn't it?\" is wrong; \"didn't you?\" is right.","tr":"Onay sorusu (question tag), bir cümlenin sonundaki kısa sorudur: \"You're Deniz, aren't you?\", \"The traffic was terrible, wasn't it?\" Sohbette karşındakini onaylamaya ve konuşmaya davet eder. Onay sorusunu cümleden kur: yardımcı fiili (am/is/are, do/does/did, have, can, will) ve zamiri tekrarla, olumluyu olumsuza çevir: \"You came by bus, didn't you?\", \"You haven't been to Dubai before, have you?\" Türkçedeki \"değil mi?\" her zaman aynı kaldığı için öğrenciler her şeyden sonra \"isn't it?\" der. İngilizcede onay sorusu cümleye uymalı: \"You came by bus, isn't it?\" yanlış; \"didn't you?\" doğru.","fa":"question tag یک سؤال کوتاه است که به آخر جمله‌ی خبری اضافه می‌شود: «⁨You're Deniz, aren't you?⁩» و «⁨The traffic was terrible, wasn't it?⁩» در گپ کوتاه، این سؤال طرف مقابل را دعوت می‌کند که تأیید کند و حرف را ادامه دهد. روش ساختنش: فعل کمکی جمله (am/is/are، do/does/did، have، can، will) و ضمیر فاعل را تکرار کن و جمله‌ی مثبت را منفی کن (و برعکس): «⁨You came by bus, didn't you?⁩» و «⁨You haven't been to Dubai before, have you?⁩» در فارسی «نه؟» یا «مگه نه؟» همیشه ثابت است، برای همین زبان‌آموزها اغلب بعد از هر جمله‌ای «⁨isn't it?⁩» می‌گویند. اما در انگلیسی tag باید با فعل جمله جور باشد: «⁨You came by bus, isn't it?⁩» غلط است و «⁨didn't you?⁩» درست."},"formsTable":{"headers":{"en":["Statement","Tag"],"tr":["Cümle","Onay sorusu"],"fa":["جمله","tag"]},"rows":[["You're Deniz,","aren't you?"],["You came by bus,","didn't you?"],["You haven't been to Dubai before,","have you?"],["It's hot today,","isn't it?"]]},"wrong":"You came by bus, isn't it?","right":"You came by bus, didn't you?","blank":{"sentence":"You're Deniz, ___?","word":"aren't you","distractors":["isn't it","don't you"]},"wrong2":"You haven't been to Dubai before, haven't you?","right2":"You haven't been to Dubai before, have you?","blank2":{"sentence":"You haven't been to Dubai before, ___?","word":"have you","distractors":["haven't you","did you"]},"useIn":{"en":"B2 track: use at least two question tags in the lobby small talk, one after a positive and one after a negative statement.","tr":"B2 yolu: lobideki sohbette en az iki onay sorusu (question tag) kullan; biri olumlu, biri olumsuz bir cümleden sonra.","fa":"مسیر B2: در گپ لابی دست‌کم دو question tag به کار ببر: یکی بعد از جمله‌ی مثبت و یکی بعد از جمله‌ی منفی."},"exitItem":{"from":"hr-1-4","kind":"blank","prompt":"You came by bus, ___?","options":["isn't it","didn't you","did you"],"correct":1,"why":{"en":"didn't you: a positive past sentence takes a negative past tag. 'Isn't it' doesn't match came, and 'did you' keeps it positive.","tr":"didn't you: olumlu geçmiş zaman cümlesi olumsuz geçmiş soru eki alır. 'Isn't it' came ile eşleşmez; 'did you' onu olumlu bırakır.","fa":"didn't you درست است، چون جمله‌ی مثبت گذشته دنباله‌ی سؤالی منفی گذشته می‌گیرد. isn't it با came جور نیست و did you مثبت می‌ماند."}},"expParts":{"hook":{"en":"'You're Deniz, aren't you?' A tiny question at the end invites him to agree and keep talking.","tr":"'You're Deniz, aren't you?' Sondaki minik soru onu onaylamaya ve konuşmaya davet eder.","fa":"«⁨You're Deniz, aren't you?⁩» یک سؤال کوچک در آخر جمله از او می‌خواهد تأیید کند و گفتگو را ادامه بدهد."},"tryWhy":{"en":"have you: the statement is negative (haven't), so the tag is positive and repeats have.","tr":"have you: cümle olumsuz (haven't), bu yüzden onay sorusu olumlu olur ve have'i tekrar eder.","fa":"جواب have you است: جمله منفی است (haven't)، پس tag مثبت می‌شود و همان have را تکرار می‌کند."},"rule":[{"en":"Repeat the helper verb and the pronoun.","tr":"Yardımcı fiili ve zamiri tekrar et.","fa":"فعل کمکی و ضمیر را تکرار کن.","ex":"You're Deniz, aren't you?"},{"en":"No helper in the statement? Use do, does or did.","tr":"Cümlede yardımcı fiil yok mu? do, does ya da did kullan.","fa":"در جمله فعل کمکی نیست؟ از do، does یا did استفاده کن.","ex":"You came by bus, didn't you?"},{"en":"Positive statement, negative tag; negative statement, positive tag.","tr":"Olumlu cümleye olumsuz onay sorusu; olumsuz cümleye olumlu onay sorusu.","fa":"بعد از جمله‌ی مثبت tag منفی می‌آید و بعد از جمله‌ی منفی tag مثبت.","ex":"You haven't been here before, have you?"}],"test":{"en":"Cover the tag. Which helper is in the statement (or hiding in the verb)? Your tag uses that one.","tr":"Onay sorusunu kapat. Cümlede hangi yardımcı fiil var (ya da fiilin içinde saklı)? Senin onay sorun da onu kullanır.","fa":"tag را بپوشان. در جمله کدام فعل کمکی هست (یا در دل فعل پنهان شده)؟ tag تو همان را به کار می‌برد."},"contrast":{"en":"Turkish 'değil mi?' and the Persian 'na?' never change, so learners add 'isn't it?' to everything. English tags change with every sentence.","tr":"Türkçedeki 'değil mi?' hiç değişmez; bu yüzden her cümleye 'isn't it?' eklenir. İngilizcede onay sorusu her cümleye göre değişir: didn't you?, have you?, aren't you?","fa":"«نه؟» یا «مگه نه؟» در فارسی هیچ‌وقت عوض نمی‌شود؛ برای همین فارسی‌زبان‌ها بعد از هر جمله‌ای «⁨isn't it?⁩» می‌گذارند. در انگلیسی tag با هر جمله عوض می‌شود: ⁨didn't you?⁩، ⁨have you?⁩، ⁨aren't you?⁩"}},"errorWatch":[{"find":["by bus, isn't it","by car, isn't it","by metro, isn't it","you're deniz, isn't it","you are deniz, isn't it","you came, isn't it","you work here, isn't it"],"fix":{"en":"Match the tag to the statement: 'You came by bus, didn't you?'","tr":"Onay sorusunu cümleye uydur: 'You came by bus, didn't you?'","fa":"tag را با جمله هماهنگ کن: «⁨You came by bus, didn't you?⁩»"}},{"find":["before, haven't you","haven't been, haven't you","isn't here, isn't it","don't you, don't you"],"fix":{"en":"A negative statement takes a positive tag: 'You haven't been here before, have you?'","tr":"Olumsuz cümle olumlu onay sorusu alır: 'You haven't been here before, have you?'","fa":"جمله‌ی منفی tag مثبت می‌گیرد: «⁨You haven't been here before, have you?⁩»"}}]},"vocab":{"id":"c-hr-1-4-v","level":"B1","category":"vocab","course":"hr","unit":"hr-1-4","goals":["career"],"title":{"en":"Small Talk","tr":"Sohbet","fa":"گپ کوتاه"},"cards":[{"word":"small talk","sentence":"Two minutes of small talk can calm a nervous candidate.","meaning":{"en":"Light conversation about unimportant topics.","tr":"havadan sudan sohbet.","fa":"صحبت سبک و دوستانه درباره‌ی موضوع‌های کم‌اهمیت"}},{"word":"rapport","sentence":"Good interviewers build rapport in the first minute.","meaning":{"en":"A friendly, trusting connection.","tr":"yakınlık, güven bağı.","fa":"رابطه‌ی گرم و مبتنی بر اعتماد"}},{"word":"Did you find us okay?","sentence":"Welcome! Did you find us okay?","meaning":{"en":"A friendly question to someone who just arrived.","tr":"Bizi kolay buldunuz mu?","fa":"آدرس را راحت پیدا کردید؟ (سؤالی دوستانه از کسی که تازه رسیده)"}},{"word":"How was your journey?","sentence":"How was your journey? Was there much traffic?","meaning":{"en":"A safe question to open a conversation.","tr":"Yolculuk nasıldı?","fa":"مسیر چطور بود؟ راحت رسیدید؟"}},{"word":"Can I get you a coffee?","sentence":"Can I get you a coffee or some water?","gap":"Can I get you a coffee","accept":["can i get you a coffee"],"meaning":{"en":"A polite offer of a drink.","tr":"Size bir kahve getireyim mi?","fa":"قهوه میل دارید؟ (تعارف مؤدبانه‌ی نوشیدنی)"}},{"word":"make yourself at home","sentence":"Please sit down and make yourself at home.","meaning":{"en":"Feel comfortable.","tr":"rahatınıza bakın; kendinizi evinizde hissedin.","fa":"راحت باشید؛ اینجا را مثل خانه‌ی خودتان بدانید"}},{"word":"lobby","sentence":"He waited in the lobby for ten minutes.","meaning":{"en":"The entrance hall of a building.","tr":"giriş holü.","fa":"لابی؛ سالن ورودی ساختمان"}},{"word":"nervous","sentence":"Many candidates feel nervous at the start.","meaning":{"en":"Worried and a little afraid.","tr":"gergin.","fa":"نگران؛ مضطرب"}},{"word":"by the way","sentence":"By the way, have you been to our Dubai office?","meaning":{"en":"Used to add a new, light topic.","tr":"bu arada.","fa":"راستی..."}},{"word":"Nice talking to you","sentence":"Nice talking to you. See you in the interview room.","meaning":{"en":"A friendly way to end a short chat.","tr":"Sizinle konuşmak güzeldi.","fa":"از هم‌صحبتی با شما خوشحال شدم"}}]},"story":{"id":"c-hr-1-4-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-1-4","title":{"en":"The Lobby","tr":"Giriş Holü","fa":"لابی"},"text":"Deniz Aydin arrived at 9:20 for a 10:00 interview. He sat in the lobby with his folder on his knees. He was nervous, and he read his own CV for the fifth time.\n\nAt 9:50 Leyla came down the stairs. She had practised a serious voice for this moment, but when she saw his face, she threw it away.\n\n\"Deniz? I'm Leyla. We spoke on the phone. Thanks for your voicemail, by the way.\" She smiled. \"Did you find us okay? The bus stop is a bit hidden.\"\n\n\"Yes, thank you. A woman at the bakery showed me.\"\n\n\"That's the best way to find anything in Istanbul,\" Leyla said. \"Can I get you a coffee or some water?\"\n\n\"Water, please.\" He relaxed a little. \"I've never been in a company like this. Only small garages.\"\n\n\"Have you ever visited Dubai?\" she asked, because the job was in Dubai. It was a safe question and a useful one.\n\n\"Never. I've seen it on TV. Have you?\"\n\n\"Twice, for work. I went last spring and it was hot in a way I can't describe.\" They both laughed.\n\nBy the time they reached the interview room, his hands were still. Leyla thought: three minutes of small talk, a little rapport, and now I will hear his real answers.\n\nIt did not seem like a lot. But in the lobby Deniz had decided that she was fair, and that decision would change how he answered every question.","vocab":[{"word":"folder","en":"A thin case for papers.","tr":"dosya","fa":"پوشه"},{"word":"hidden","en":"Hard to see or find.","tr":"gizli, saklı","fa":"پنهان؛ دور از چشم"},{"word":"relax","en":"To become calm.","tr":"rahatlamak","fa":"آرام گرفتن؛ از استرس درآمدن"},{"word":"fair","en":"Treating people equally and honestly.","tr":"adil","fa":"منصف؛ عادل"},{"word":"knees","en":"The middle part of your legs.","tr":"dizler","fa":"زانوها"}],"quiz":[{"prompt":"Why did Leyla ask about Dubai?","options":["It was a safe question and connected to the job","She wanted to go on holiday","She did not know what else to say"],"correct":0},{"prompt":"Choose the correct sentence.","options":["I have been to Dubai last spring.","I went to Dubai last spring.","I have went to Dubai last spring."],"correct":1},{"prompt":"Which question did Deniz ask back to Leyla?","options":["Have you?","Did you find us?","Can I get you a coffee?"],"correct":0},{"prompt":"What did Deniz decide in the lobby?","options":["That Leyla was fair","That the job was too far away","That he wanted to leave"],"correct":0}],"notice":{"en":"Leyla has three minutes in the lobby before the interview. Count her questions. Which one is about experience?","tr":"Leyla'nın mülakattan önce lobide üç dakikası var. Sorularını say. Hangisi deneyimle ilgili?","fa":"لیلا پیش از مصاحبه سه دقیقه در لابی وقت دارد. سؤال‌هایش را بشمار. کدام یکی درباره‌ی تجربه است؟"},"bridge":{"en":"'Have you ever visited Dubai?' and 'I went last spring' sit side by side in the story. Next: see why.","tr":"Hikâyede 'Have you ever visited Dubai?' ve 'I went last spring' yan yana. Sırada: nedenini gör.","fa":"در داستان «⁨Have you ever visited Dubai?⁩» و «I went last spring» کنار هم آمده‌اند. قدم بعد: ببین چرا."}},"speaking":{"id":"hr-1-4","course":"hr","unit":"hr-1-4","topic":{"en":"Small Talk Before an Interview","tr":"Mülakat Öncesi Sohbet","fa":"گپ کوتاه پیش از مصاحبه"},"warmup":{"en":"What is one safe small-talk question you like to ask someone you have just met?","tr":"Yeni tanıştığın biriyle sohbette sorduğun güvenli bir soru nedir?","fa":"تو وقتی با کسی تازه آشنا می‌شوی، دوست داری چه سؤال بی‌خطری از او بپرسی؟"},"questions":[{"en":"Greet a candidate in the lobby. Ask about their journey.","tr":"Bir adayı lobide karşıla. Yolculuğunu sor.","fa":"به متقاضی در لابی خوشامد بگو و بپرس مسیر چطور بود."},{"en":"Offer a drink and ask one experience question: \"Have you ever...?\"","tr":"Bir içecek ikram et ve bir deneyim sorusu sor: \"Have you ever...?\"","fa":"یک نوشیدنی تعارف کن و یک سؤال درباره‌ی تجربه بپرس: «⁨Have you ever...?⁩»"},{"en":"End the small talk and move to the interview room.","tr":"Sohbeti bitir ve mülakat odasına geç.","fa":"گپ را مؤدبانه تمام کن و او را به اتاق مصاحبه راهنمایی کن."}],"followups":[{"en":"The candidate gives a one-word answer. Ask a gentle follow-up so they talk more.","tr":"Aday tek kelimelik cevap verdi. Daha çok konuşması için nazik bir takip sorusu sor.","fa":"متقاضی فقط یک کلمه جواب داده است. یک سؤال تکمیلیِ ملایم بپرس تا بیشتر صحبت کند."},{"en":"Now welcome a visitor to your own workplace: one question, one comment and a way in.","tr":"Şimdi kendi iş yerine gelen bir misafiri karşıla: bir soru, bir yorum ve içeri davet.","fa":"حالا مهمانی را در محل کار خودت خوشامد بگو: یک سؤال، یک جمله و دعوت به داخل."}],"expressions":[{"phrase":"Did you find us okay?","meaning":{"en":"Friendly opener for a visitor.","tr":"Ziyaretçi için samimi açılış.","fa":"شروعی دوستانه برای مهمانی که تازه رسیده است."}},{"phrase":"Have you ever been to...?","meaning":{"en":"Asks about experience.","tr":"Deneyim sorar.","fa":"درباره‌ی تجربه‌ی کسی می‌پرسد."}},{"phrase":"Shall we make a start?","meaning":{"en":"Moves from small talk to business.","tr":"Sohbetten işe geçer.","fa":"از گپ به سراغ اصل کار می‌رود."}}],"culture":{"en":"In the UK and US, a few minutes of light talk before business is normal and often expected. In some other cultures, getting to the point fast shows respect for time. Neither is wrong: watch how the other person reacts and adjust.","tr":"Birleşik Krallık ve ABD'de işe girmeden önce birkaç dakika hafif sohbet normaldir, çoğu zaman beklenir. Bazı kültürlerde hemen konuya girmek zamana saygıdır. İkisi de yanlış değil: karşındakinin tepkisine bakıp uyum sağla.","fa":"در بریتانیا و آمریکا چند دقیقه گپ سبک پیش از شروع کار عادی است و اغلب از تو انتظار می‌رود. در بعضی فرهنگ‌های دیگر، زود رفتن سر اصل مطلب نشانه‌ی احترام به وقت دیگران است. هیچ‌کدام غلط نیست؛ واکنش طرف مقابل را ببین و خودت را با آن هماهنگ کن."},"model":"Good morning, you must be Deniz. I'm Leyla, we spoke on the phone. How was your journey? Did you find us okay? The bus stop is a bit hidden. Can I get you some water or a coffee? Make yourself at home. Have you ever been to Dubai? Not yet? I went there last spring, and it was very hot! Right, shall we make a start? The interview room is just upstairs.","selfCheck":[{"en":"I asked about the journey.","tr":"Yolculuğu sordum.","fa":"درباره‌ی مسیر رسیدنش پرسیدم."},{"en":"I asked one 'Have you ever...?' question.","tr":"Bir tane 'Have you ever...?' sorusu sordum.","fa":"یک سؤال با «⁨Have you ever...?⁩» پرسیدم."},{"en":"With a finished time I used the past simple (I went...).","tr":"Bitmiş bir zamanla past simple kullandım (I went...).","fa":"برای زمان تمام‌شده از گذشته‌ی ساده استفاده کردم (⁨I went...⁩)."},{"en":"I ended the small talk with 'Shall we make a start?'","tr":"Sohbeti 'Shall we make a start?' ile bitirdim.","fa":"گپ را با «⁨Shall we make a start?⁩» تمام کردم."}]},"writing":{"id":"c-hr-1-4-w","title":{"en":"A welcome message to a candidate","tr":"Adaya hoş geldin mesajı","fa":"پیام خوشامد به متقاضی"},"course":"hr","unit":"hr-1-4","type":"writing","difficulty":"easy","prompt":{"en":"Write a short, friendly message (3-4 sentences) to a candidate before the interview: welcome, an offer of help finding the office and one small-talk question.","tr":"Mülakat öncesi bir adaya kısa ve samimi bir mesaj yaz (3-4 cümle): karşılama, ofisi bulmasına yardım teklifi ve bir sohbet sorusu.","fa":"پیش از مصاحبه یک پیام کوتاه و دوستانه (سه تا چهار جمله) برای متقاضی بنویس: خوشامدگویی، پیشنهاد کمک برای پیدا کردن دفتر و یک سؤال برای گپ کوتاه."},"model":"Hi Deniz, we're looking forward to meeting you tomorrow at our head office. The bus stop is a bit hidden, so please call me if you can't find us. Have you ever visited our part of the city? See you at 10:00. Kind regards, Leyla","frame":"Hi ___, we're looking forward to ___. ___ is a bit hidden, so please ___. Have you ever ___? See you at ___. Kind regards, ___","words":[{"word":"looking forward to"},{"word":"have you ever"},{"word":"hidden"}],"minWords":35,"minSentences":4,"rubric":["Task done: welcome, help offer, small-talk question","Organised: greeting, info, question, close","Language: present perfect for experience; -ing after looking forward to","Tone: warm, safe topic"],"rubricI18n":{"tr":["Görev: karşılama, yardım teklifi, sohbet sorusu","Düzen: selamlama, bilgi, soru, kapanış","Dil: deneyim için present perfect; looking forward to'dan sonra -ing","Üslup: sıcak, güvenli bir konu"],"fa":["کامل بودن کار: خوشامد، پیشنهاد کمک، یک سؤال برای گپ کوتاه","نظم: سلام، اطلاعات، سؤال، پایان","زبان: حال کامل برای تجربه؛ ‎-ing بعد از looking forward to","لحن: گرم، با موضوعی بی‌خطر"]},"portfolio":null,"parts":[{"t":{"en":"A welcome","tr":"Bir karşılama","fa":"خوشامد"},"find":["looking forward to","welcome","great to"],"sample":"looking forward to meeting you tomorrow"},{"t":{"en":"An offer of help to find you","tr":"Yolu bulması için yardım teklifi","fa":"پیشنهاد کمک برای پیدا کردن دفتر"},"find":["call me","if you can't find","let me know","help"],"sample":"the bus stop is hidden, call me"},{"t":{"en":"One small-talk question","tr":"Bir sohbet sorusu","fa":"یک سؤال گپ‌وگفت"},"find":["have you ever","how was","do you","are you"],"sample":"Have you visited this part of the city?"}]},"perspective":{"id":"c-hr-1-4-p","title":{"en":"Deniz in the lobby","tr":"Lobide Deniz","fa":"دنیز در لابی"},"course":"hr","unit":"hr-1-4","type":"perspective","minSentences":3,"prompt":{"en":"You are Deniz in the lobby, 9:40. Write 3 sentences of inner monologue in first person: what are you thinking and feeling?","tr":"Saat 9:40'ta lobide Deniz'sin. Birinci tekil şahısla 3 cümlelik iç monolog yaz: ne düşünüyor ve ne hissediyorsun?","fa":"تو دنیز هستی و ساعت ۹:۴۰ در لابی منتظر نشسته‌ای. سه جمله از حرف‌هایی که در دلت می‌گذرد، از زبان خودت بنویس: به چه فکر می‌کنی و چه حسی داری؟"}},"exit":{"id":"c-hr-1-4-x","course":"hr","unit":"hr-1-4","type":"exit","items":[{"from":"hr-1-4","kind":"blank","prompt":"Have you ever ___ in a warehouse?","options":["worked","work","working"],"correct":0,"point":2,"why":{"en":"worked: 'Have you ever' + past participle. 'Work' and 'working' are not past participles.","tr":"worked: 'Have you ever' + üçüncü hâl. 'Work' ve 'working' üçüncü hâl değildir.","fa":"worked درست است، چون Have you ever با اسم مفعول می‌آید. work و working اسم مفعول نیستند."}},{"from":"hr-1-4","kind":"blank","prompt":"I ___ to Dubai last spring.","options":["have gone","went","have been"],"correct":1,"point":2,"why":{"en":"went: 'last spring' is a finished time, so past simple. 'Have gone' and 'have been' can't go with a finished time.","tr":"went: 'last spring' bitmiş bir zamandır, bu yüzden past simple. 'Have gone' ve 'have been' bitmiş zamanla kullanılmaz.","fa":"went درست است، چون last spring زمان تمام‌شده است و گذشته‌ی ساده می‌خواهد. have gone و have been با زمان تمام‌شده نمی‌آیند."}},{"from":"hr-1-4","kind":"mcq","prompt":"A visitor from a supplier gives one-word answers to your small talk and opens her laptop. What do you do?","options":["Keep the chat short and move on to the meeting","Ask more questions until she relaxes","Tell her that small talk is normal here"],"correct":0,"point":4,"why":{"en":"Keep the chat short and move on to the meeting: her one-word answers and the open laptop show she wants to start. Small talk is normal in many offices, but you watch the other person and adjust. More questions, or a talk about habits here, only keep her waiting.","tr":"Keep the chat short and move on to the meeting: Tek kelimelik cevapları ve dizüstü bilgisayarını açması, bir an önce başlamak istediğini gösteriyor. Birçok ofiste kısa bir sohbet normaldir, ama karşındakini izleyip ona göre davranırsın. Daha çok soru sormak ya da buradaki alışkanlıkları anlatmak onu yalnızca bekletir.","fa":"«⁨Keep the chat short and move on to the meeting⁩» درست است: جواب‌های یک‌کلمه‌ای و لپ‌تاپی که باز کرده نشان می‌دهد می‌خواهد زودتر کار را شروع کند. گپ کوتاه در خیلی از دفترها عادی است، ولی واکنش طرف مقابل را می‌بینی و خودت را با آن هماهنگ می‌کنی. سؤال بیشتر یا توضیح دادن عادت‌های این‌جا فقط او را معطل می‌کند."},"hint2":{"en":"Small talk is normal in many offices, but read the other person first. What do her short answers and the open laptop tell you she wants?","tr":"Birçok ofiste kısa bir sohbet normaldir, ama önce karşındakini gözlemle. Kısa cevaplarından ve dizüstü bilgisayarını açmasından onun ne istediğini anlayabilir misin?","fa":"گپ کوتاه در خیلی از دفترها عادی است، ولی اول به طرف مقابل دقت کن. از جواب‌های کوتاهش و لپ‌تاپی که باز کرده می‌فهمی چه می‌خواهد؟"}},{"from":"hr-1-3","kind":"blank","prompt":"Sorry, did you ___ Monday or Sunday?","options":["said","say","saying"],"correct":1,"point":2,"why":{"en":"say: after 'did you', use the plain verb. 'Said' doubles the past, and 'saying' isn't a verb form here.","tr":"say: 'did you'dan sonra yalın fiil gelir. 'Said' geçmişi iki kez söyler; 'saying' burada fiil biçimi değildir.","fa":"say درست است، چون بعد از did you فعل ساده می‌آید. said گذشته را دو بار می‌گوید و saying اینجا شکل فعل نیست."}},{"from":"hr-1-2","kind":"mcq","prompt":"Which request is polite and correct?","options":["Would you mind sending me the form?","Would you mind to send me the form?","Send me form ASAP."],"correct":0,"point":2,"why":{"en":"'Would you mind sending me the form?' uses mind + -ing. 'Mind to send' is wrong, and 'Send me form ASAP' is an order with no article.","tr":"'Would you mind sending me the form?' mind + -ing kullanır. 'Mind to send' yanlıştır; 'Send me form ASAP' artikelsiz bir emirdir.","fa":"«Would you mind sending me the form?» با mind و فعل ing‌دار درست است. mind to send غلط است و «Send me form ASAP» دستوری بی‌ادبانه و بدون حرف تعریف است."}},{"from":"hr-1-1","kind":"blank","prompt":"Our Dubai branch ___ twelve drivers now.","options":["is having","has","are having"],"correct":1,"point":2,"why":{"en":"has: 'have' for owning is a state, so present simple, with -s for one branch. 'Is having' and 'are having' are wrong for a state.","tr":"has: sahip olmak anlamındaki 'have' bir durumdur; tek bir şube için -s'li geniş zaman. 'Is having' ve 'are having' durum için yanlıştır.","fa":"⁨has⁩ درست است، چون ⁨have⁩ به معنی داشتن حالت است و برای یک شعبه حال ساده با ⁨-s⁩ می‌آید. ⁨is having⁩ و ⁨are having⁩ برای حالت غلط‌اند."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
